{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/faq-list.json
    A section with a heading and the questions. Axes: layout (accordion: native disclosures that open without script; chat: question and answer as alternating bubbles), columns (1, 2), search mode (none, field: a search field above; the page filters by `search.query`), filter mode (none, categories: tabs above; the page filters by `filter.category`), density, tone.
    Props (p): id, title, items, search, filter, layout, cols, multiple, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_items = ($p['items'] ?? null)}
{var $v_search = ($p['search'] ?? null)}
{var $v_filter = ($p['filter'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'accordion')}
{var $v_cols = ($p['cols'] ?? '1')}
{var $v_multiple = ($p['multiple'] ?? false)}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{var $v_inCategory = ui_where($v_items, 'category', ui_get($v_filter, ['category']))}
{var $v_shown = ui_match($v_inCategory, 'question', ui_get($v_search, ['query']))}
{capture $c_13}
  {if ui_t(ui_eq(ui_get($v_search, ['mode']), 'field'))}
    {=ui_include('blocks/search-field.latte', ['p' => ['label' => ui_coalesce([ui_get($v_search, ['label']), '']), 'placeholder' => ui_get($v_search, ['label']), 'value' => ui_coalesce([ui_get($v_search, ['query']), ''])]])|noescape}
  {/if}
  {if ui_t(ui_eq(ui_get($v_filter, ['mode']), 'categories'))}
    {capture $c_2}
      {foreach ui_l(ui_get($v_filter, ['tabs'])) as $v_tab}
        {capture $c_1}
          {=ui_text(ui_get($v_tab, ['title']))}
        {/capture}
        {=ui_include('blocks/switcher-item.latte', ['p' => ['active' => ui_eq(ui_get($v_tab, ['value']), ui_get($v_filter, ['category']))], 'children' => $c_1])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('blocks/switcher.latte', ['p' => ['label' => ui_get($v_filter, ['label'])], 'children' => $c_2])|noescape}
  {/if}
  {if ui_t(ui_eq($v_layout, 'chat'))}
    {capture $c_8}
      {foreach ui_l($v_shown) as $v_item}
        {capture $c_7}
          {capture $c_4}
            {capture $c_3}
              {=ui_text(ui_get($v_item, ['question']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_3])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'ml-auto max-w-xs sm:max-w-md rounded bg-primary px-4 py-4 text-primary-foreground'], 'children' => $c_4])|noescape}
          {capture $c_6}
            {capture $c_5}
              {=ui_text(ui_get($v_item, ['answer']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm'], 'children' => $c_5])|noescape}
          {/capture}
          {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'mr-auto max-w-xs sm:max-w-md rounded bg-muted px-4 py-4'], 'children' => $c_6])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'faq-item'])], 'children' => $c_7])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'faq'])], 'children' => $c_8])|noescape}
  {else}
    {capture $c_12}
      {foreach ui_l($v_shown) as $v_item}
        {capture $c_11}
          {capture $c_9}
            {=ui_text(ui_get($v_item, ['question']))}
          {/capture}
          {=ui_include('ui/disclosure/summary.latte', ['p' => ['Variant' => 'item'], 'children' => $c_9])|noescape}
          {capture $c_10}
            {=ui_text(ui_get($v_item, ['answer']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'pb-4 text-muted-foreground'], 'children' => $c_10])|noescape}
        {/capture}
        {=ui_include('ui/disclosure/disclosure.latte', ['p' => ['Variant' => 'item', 'Name' => ui_s((ui_t($v_multiple) ? null : ui_tpl('{0}-faq', [ui_coalesce([$v_id, 'faq'])]))), 'Attrs' => ui_attrs(['data-testid', 'faq-item'])], 'children' => $c_11])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_cols, '2')) ? '1-2' : '1')), 'Class' => 'items-start gap-x-8', 'Attrs' => ui_attrs(['data-testid', 'faq'])], 'children' => $c_12])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'measure' => (ui_t(ui_eq($v_layout, 'chat')) ? '2xl' : 'default'), 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_13])|noescape}
